{
  "findings": [
    {
      "check_id": "CKV_GCP_28",
      "title": "Ensure that Cloud Storage bucket is not anonymously or publicly accessible",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly restrict public access, which could lead to unauthorized access to sensitive data."
    },
    {
      "check_id": "CKV_GCP_29",
      "title": "Ensure that Cloud Storage buckets have uniform bucket-level access enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "Uniform bucket-level access is not enabled, which could lead to inconsistent access control policies."
    },
    {
      "check_id": "CKV_GCP_114",
      "title": "Ensure public access prevention is enforced on Cloud Storage bucket",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "Public access prevention is not explicitly enforced, which could allow unintended public access."
    },
    {
      "check_id": "CKV_GCP_62",
      "title": "Bucket should log access",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled, which makes it difficult to monitor and audit access to the bucket."
    }
  ],
  "patched_code": "resource \"google_storage_bucket\" \"compliance_storage\" {\n  name     = \"${var.project_id}-digital-asset-trading-platform-compliance\"\n  location = var.region\n\n  versioning {\n    enabled = true\n  }\n\n  lifecycle_rule {\n    condition {\n      age = 2555\n    }\n    action {\n      type = \"Delete\"\n    }\n  }\n\n  uniform_bucket_level_access = true\n\n  public_access_prevention = \"enforced\"\n\n  logging {\n    log_bucket        = \"${var.project_id}-logging-bucket\"\n    log_object_prefix = \"compliance-storage-logs\"\n  }\n\n  iam_policy {\n    bindings {\n      role    = \"roles/storage.objectViewer\"\n      members = [\"user:authorized-user@example.com\"]\n    }\n  }\n}",
  "fix_summary": "Added `uniform_bucket_level_access` to enforce uniform access control. Enabled `public_access_prevention` to block public access. Configured access logging with a logging bucket and prefix. Added an IAM policy to restrict access to authorized users."
}
